	// Control: the same read issued through the node that is the actual leader
	// of the remaining configuration.
	if err := n2.Step(&pb.Message{
		From:    new(uint64(2)),
		To:      new(uint64(2)),
		Type:    pb.MsgReadIndex.Enum(),
		Entries: []*pb.Entry{{Data: []byte("R")}},
