		last := n1.readStates[len(n1.readStates)-1].Index
		ev["read_index"] = last
		ev["same_stale_index_as_first"] = last == n1.readStates[0].Index
		ev["still_leader_and_same_term"] = n1.state == StateLeader && n1.Term == 1
	}
