		"event":             "fwd_readindex_stashed",
		"case":              name,
		"node":              1,
		"pending_reads":     len(n1.pendingReadIndexMessages),
		"node2_read_states": len(peers[2].readStates),
	}
	for k, v := range assuranceDutyState(n1) {
		ev[k] = v
