		tick, tcancel := context.WithTimeout(ctx, timeout)
		defer tcancel()
		select {
		case rd := <-h.Ready():
			var toNode1 []*pb.Message
			for _, m := range rd.Messages {
				if m.GetTo() == 1 {
					toNode1 = append(toNode1, m)
				}
			}
