	// draining one of node 2's Readys until neither side produces anything.
	pump := func() {
		for i := 0; i < 50; i++ {
			progressed := false
			for _, m := range n1.readMessages() {
				if m.GetTo() == 2 {
					if err := h.Step(ctx, m); err != nil {
						t.Logf("node 2 step: %v", err)
					}
