	// new leader, so the shortcut answers it exactly as without CheckQuorum.
	if err := n1.Step(&pb.Message{From: new(uint64(1)), To: new(uint64(1)), Type: pb.MsgReadIndex.Enum(),
		Entries: []*pb.Entry{{Data: []byte("R")}}}); err != nil {
