	})

	// A further read is not answered at all.
	before := len(n1.readStates)
	if err := n1.Step(&pb.Message{From: new(uint64(1)), To: new(uint64(1)), Type: pb.MsgReadIndex.Enum(),
		Entries: []*pb.Entry{{Data: []byte("R2")}}}); err != nil {
