func stepLeader(r *raft, m *pb.Message) error {
	// These message types do not require any progress for m.From.
	switch m.GetType() {
	case pb.MsgBeat:
		r.bcastHeartbeat()
		return nil
	case pb.MsgCheckQuorum:
		if !r.trk.QuorumActive() {
			r.logger.Warningf("%x stepped down to follower since quorum is not active", r.id)
			r.becomeFollower(r.Term, None)
		}

case pb.MsgProp:
	if len(m.GetEntries()) == 0 {
		r.logger.Panicf("%x stepped empty MsgProp", r.id)
	}
	if r.trk.Progress[r.id] == nil {
		// If we are not currently a member of the range (i.e. this node
		// was removed from the configuration while serving as leader),
		// drop any new proposals.
		return ErrProposalDropped
	}

r.logger.Infof("%x switched to configuration %s", r.id, r.trk.Config)
cs := r.trk.ConfState()
pr, ok := r.trk.Progress[r.id]

// Update whether the node itself is a learner, resetting to false when the
// node is removed.
r.isLearner = ok && pr.IsLearner

if (!ok || r.isLearner) && r.state == StateLeader {
	// This node is leader and was removed or demoted, step down if requested.
	//
	// We prevent demotions at the time writing but hypothetically we handle
	// them the same way as removing the leader.
	//
	// TODO(tbg): ask follower with largest Match to TimeoutNow (to avoid
	// interruption). This might still drop some proposals but it's better than
	// nothing.
	if r.stepDownOnRemoval {
		r.becomeFollower(r.Term, None)
	}
	return cs
}

// The remaining steps only make sense if this node is the leader and there
// are other nodes.
if r.state != StateLeader || len(cs.Voters) == 0 {
	return cs
}

// StepDownOnRemoval makes the leader step down when it is removed from the
// group or demoted to a learner.
//
// This behavior will become unconditional in the future. See:
// https://github.com/etcd-io/raft/issues/83
StepDownOnRemoval bool

// ReadOnlyOption specifies how the read only request is processed.
//
// ReadOnlySafe guarantees the linearizability of the read only request by
// communicating with the quorum. It is the default and suggested option.
//
// ReadOnlyLeaseBased ensures linearizability of the read only request by
// relying on the leader lease. It can be affected by clock drift.
// If the clock drift is unbounded, leader might keep the lease longer than it
// should (clock can move backward/pause without any bound). ReadIndex is not safe
// in that case.
// CheckQuorum MUST be enabled if ReadOnlyOption is ReadOnlyLeaseBased.
ReadOnlyOption ReadOnlyOption

case cc := <-n.confc:
	_, okBefore := r.trk.Progress[r.id]
	cs := r.applyConfChange(cc)
	// If the node was removed, block incoming proposals. Note that we
	// only do this if the node was in the config before. Nodes may be
	// a member of the group without knowing this (when they're catching
	// up on the log and don't have the latest config) and we don't want
	// to block the proposal channel in that case.
	//
	// NB: propc is reset when the leader changes, which, if we learn
	// about it, sort of implies that we got readded, maybe? This isn't
	// very sound and likely has bugs.
	if _, okAfter := r.trk.Progress[r.id]; okBefore && !okAfter {
		var found bool
		for _, sl := range [][]uint64{cs.Voters, cs.VotersOutgoing} {
			for _, id := range sl {
				if id == r.id {
					found = true
					break
				}
			}
			if found {
				break
			}
		}
		if !found {
			propc = nil
		}
	}
	select {
	case n.confstatec <- cs:
	case <-n.done:
	}

func (n *node) run() {
	var propc chan msgWithResult
	var readyc chan Ready
	var advancec chan struct{}
	var rd Ready

	r := n.rn.raft

	lead := None

	for {
		if advancec == nil && n.rn.HasReady() {
			// Populate a Ready. Note that this Ready is not guaranteed to
			// actually be handled. We will arm readyc, but there's no guarantee
			// that we will actually send on it. It's possible that we will
			// service another channel instead, loop around, and then populate
			// the Ready again. We could instead force the previous Ready to be
			// handled first, but it's generally good to emit larger Readys plus
			// it simplifies testing (by emitting less frequently and more
			// predictably).
			rd = n.rn.readyWithoutAccept()
			readyc = n.readyc
		}

		if lead != r.lead {
			if r.hasLeader() {
				if lead == None {
					r.logger.Infof("raft.node: %x elected leader %x at term %d", r.id, r.lead, r.Term)
				} else {
					r.logger.Infof("raft.node: %x changed leader from %x to %x at term %d", r.id, lead, r.lead, r.Term)
				}
				propc = n.propc
			} else {
				r.logger.Infof("raft.node: %x lost leader %x at term %d", r.id, lead, r.Term)
				propc = nil
			}
			lead = r.lead
		}

func (n *node) stepWithWaitOption(ctx context.Context, m *pb.Message, wait bool) error {
	if m.GetType() != pb.MsgProp {
		select {
		case n.recvc <- m:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		case <-n.done:
			return ErrStopped
		}
	}
	ch := n.propc
	pm := msgWithResult{m: m}
	if wait {
		pm.result = make(chan error, 1)
	}
	select {
	case ch <- pm:
		if !wait {
			return nil
		}
	case <-ctx.Done():
		return ctx.Err()
	case <-n.done:
		return ErrStopped
	}
	select {
	case err := <-pm.result:
		if err != nil {
			return err
		}
	case <-ctx.Done():
		return ctx.Err()
	case <-n.done:
		return ErrStopped
	}
	return nil
}

// Propose proposes that data be appended to the log. Note that proposals can be lost without
// notice, therefore it is user's job to ensure proposal retries.
Propose(ctx context.Context, data []byte) error

case m.GetTerm() > r.Term:
	if m.GetType() == pb.MsgVote || m.GetType() == pb.MsgPreVote {
		force := bytes.Equal(m.GetContext(), []byte(campaignTransfer))
		inLease := r.checkQuorum && r.lead != None && r.electionElapsed < r.electionTimeout
		if !force && inLease {
			// If a server receives a RequestVote request within the minimum election timeout
			// of hearing from a current leader, it does not update its term or grant its vote
			last := r.raftLog.lastEntryID()
			// TODO(pav-kv): it should be ok to simply print the %+v of the lastEntryID.
			r.logger.Infof("%x [logterm: %d, index: %d, vote: %x] ignored %s from %x [logterm: %d, index: %d] at term %d: lease is not expired (remaining ticks: %d)",
				r.id, last.term, last.index, r.Vote, m.GetType(), m.GetFrom(), m.GetLogTerm(), m.GetIndex(), r.Term, r.electionTimeout-r.electionElapsed)
			return nil
		}

// responseToReadIndexReq constructs a response for `req`. If `req` comes from the peer
// itself, a blank value will be returned.
func (r *raft) responseToReadIndexReq(req *pb.Message, readIndex uint64) *pb.Message {
	if req.GetFrom() == None || req.GetFrom() == r.id {
		r.readStates = append(r.readStates, ReadState{
			Index:      readIndex,
			RequestCtx: req.GetEntries()[0].GetData(),
		})
		return &pb.Message{}
	}
	return &pb.Message{
		Type:    pb.MsgReadIndexResp.Enum(),
		To:      req.From,
		Index:   new(readIndex),
		Entries: req.GetEntries(),
	}
